function rankingEquipment(r){const out={hair:null,hat:null,glasses:null,outfit:null,bottom:null,shoes:null,bag:null,hand:null,pet:null};try{const value=JSON.parse(r.equipment_json||'{}');for(const slot of Object.keys(out)){const id=String(value?.[slot]||'');if(RANKING_ITEM_SLOTS[id]===slot)out[slot]=id}}catch{}return out}
function parseEquipment(r){const out={face:'face-round',expression:'expression-smile',hair:null,hat:null,glasses:null,outfit:null,bottom:null,shoes:null,bag:null,hand:null,pet:null};try{const v=JSON.parse(r.equipment_json||'{}');for(const slot of ['hair','hat','glasses','outfit','bottom','shoes','bag','hand','pet']){const id=String(v?.[slot]||'');if(RANKING_ITEM_SLOTS[id]===slot)out[slot]=id}if(FACE_CATALOG.some(i=>i.id===v?.face&&i.slot==='face'))out.face=v.face;if(FACE_CATALOG.some(i=>i.id===v?.expression&&i.slot==='expression'))out.expression=v.expression;return out}catch{return out}}
function inventoryFor(r){return [...FACE_CATALOG,...ITEM_CATALOG].map(item=>({id:item.id,slot:item.slot,icon:item.icon,name:item.name,condition:item.condition,unlocked:!!item.unlock(r)}))}
function sanitizeEquipment(r,equipment){const inv=inventoryFor(r),allowed=new Map(inv.filter(i=>i.unlocked).map(i=>[i.id,i]));const out={face:'face-round',expression:'expression-smile',hair:null,hat:null,glasses:null,outfit:null,bottom:null,shoes:null,bag:null,hand:null,pet:null};for(const slot of Object.keys(out)){const id=equipment?.[slot];if(id&&allowed.get(id)?.slot===slot)out[slot]=id}return out}
function activityRecordsFor(name){return db.prepare('SELECT activity_id AS activityId,attempts,best_score AS bestScore,last_score AS lastScore,total_score AS totalScore,updated_at AS updatedAt FROM activity_records WHERE player_name=? ORDER BY activity_id').all(name)}
