function safePlayer(r){const rewards=rewardsFor(r),equipment=parseEquipment(r),progress=progressFromXp(r.xp),custom=customTitleView(getSetting,r.name,progress.level);return{name:r.name,totalScore:r.total_score,attempts:r.attempts,bestScore:r.best_score,lastScore:r.last_score,loginCount:r.login_count||0,lastLoginAt:r.last_login_at||null,xp:r.xp||0,...progress,title:progress.level>=60&&custom.customTitle?custom.customTitle:rewards.title,badges:rewards.badges,nextGrowthReward:nextGrowthRewardFor(progress.level),nextNpcUnlock:nextNpcUnlockFor(progress.level),...custom,baseCharacter:compatibleBase(r.base_character),baseCharacters:BASE_CHARACTERS,inventory:inventoryFor(r),equipment,activities:activityRecordsFor(r.name),updatedAt:r.updated_at}}
function logActivity(name,type,detail=''){db.prepare('INSERT INTO activity_log(player_name,type,detail,created_at) VALUES(?,?,?,?)').run(name,type,detail,new Date().toISOString())}
const bearer=req=>{const a=String(req.headers.authorization||'');return a.startsWith('Bearer ')?a.slice(7):''};
function pruneSessions(map,ttl,now=Date.now()){for(const[token,session]of map.entries())if(now-(session?.lastSeenAt||session?.createdAt||0)>ttl)map.delete(token)}
function sessionFrom(map,token,ttl){const s=map.get(token);if(!s)return null;if(Date.now()-s.lastSeenAt>ttl){map.delete(token);return null}s.lastSeenAt=Date.now();return s}
function pruneReplacedStudentSessions(now=Date.now()){for(const[token,expiresAt]of replacedStudentSessions.entries())if(expiresAt<=now)replacedStudentSessions.delete(token)}
function requireSession(req,res,next){const token=bearer(req),s=sessionFrom(sessions,token,STUDENT_SESSION_TTL_MS);if(!s){pruneReplacedStudentSessions();if(replacedStudentSessions.has(token))return res.status(401).json({ok:false,code:'session-replaced'});return res.status(401).json({ok:false,code:'not-authenticated'})}req.session=s;next()}
function requireAdmin(req,res,next){if(!sessionFrom(adminSessions,bearer(req),ADMIN_SESSION_TTL_MS))return res.status(401).json({ok:false,code:'admin-not-authenticated'});next()}
const createSession=name=>{const t=crypto.randomBytes(32).toString('hex'),now=Date.now();pruneSessions(sessions,STUDENT_SESSION_TTL_MS,now);sessions.set(t,{name,createdAt:now,lastSeenAt:now});return t},createAdminSession=()=>{const t=crypto.randomBytes(32).toString('hex'),now=Date.now();pruneSessions(adminSessions,ADMIN_SESSION_TTL_MS,now);adminSessions.set(t,{createdAt:now,lastSeenAt:now});return t};
function normalizeRemoteAddress(value){const address=String(value||'').trim().toLowerCase();return address.startsWith('::ffff:')?address.slice(7):address}
function localTeacherAddresses(){const addresses=new Set(['127.0.0.1','::1']);try{for(const entries of Object.values(os.networkInterfaces()))for(const entry of entries||[])if(entry?.address)addresses.add(normalizeRemoteAddress(entry.address))}catch{}return addresses}
const LOCAL_TEACHER_ADDRESSES=localTeacherAddresses();
function isLocalTeacherRequest(req){return LOCAL_TEACHER_ADDRESSES.has(normalizeRemoteAddress(req.socket?.remoteAddress))}
function classroomUrls(){const u=[];for(const[adapter,entries]of Object.entries(os.networkInterfaces()))for(const n of entries||[])if(n.family==='IPv4'&&!n.internal)u.push({adapter,address:n.address,url:`http://${n.address}:${PORT}`});return u}
function prunePresence(now=Date.now()){for(const[name,seen]of presence.entries())if(now-seen>PRESENCE_TTL_MS)presence.delete(name)}
function activePresenceNames(){const now=Date.now();prunePresence(now);return new Set([...presence.entries()].filter(([,seen])=>now-seen<=45000).map(([name])=>name))}
function pruneLiveEvents(){const now=Date.now();while(liveEvents.length&&(liveEvents[0].expiresAt<=now||liveEvents.length>50))liveEvents.shift()}
function publishLiveEvent(icon,message,type='celebration'){const audience=activePresenceNames();if(!audience.size)return null;const now=Date.now(),event={id:++liveEventSeq,icon:String(icon||'✨').slice(0,8),message:String(message||'').slice(0,160),type:String(type||'celebration').slice(0,40),audience,createdAt:new Date(now).toISOString(),expiresAt:now+15000};liveEvents.push(event);pruneLiveEvents();return event}
function announceLevelUp(before,after){const oldLevel=levelFromXp(before?.xp),newLevel=levelFromXp(after?.xp);if(newLevel<=oldLevel)return null;logActivity(after.name,'level-up',`Lv.${newLevel} 달성`);return publishLiveEvent('🎉',`${after.name} 학생이 Lv.${newLevel}에 올랐습니다!`,'level-up')}
function announceNpcUnlock(before,after){const oldLevel=levelFromXp(before?.xp),newLevel=levelFromXp(after?.xp),unlocked=NPC_LEVEL_UNLOCKS.filter(npc=>oldLevel<npc.level&&newLevel>=npc.level);for(const npc of unlocked){logActivity(after.name,'npc-unlock',`Lv.${npc.level} · ${npc.name}`);publishLiveEvent(npc.icon,`${after.name} 학생이 새 마을 친구 “${npc.name}”을 만날 수 있게 되었습니다!`,'npc-unlock')}return unlocked}
function announceFeaturedAchievement(before,after){const oldIds=new Set(rewardsFor(before).badges.map(b=>b.id)),earned=rewardsFor(after).badges.filter(b=>!oldIds.has(b.id)),featured=earned.find(b=>b.id==='perfect')||earned.find(b=>b.id==='persistent');if(!featured)return null;logActivity(after.name,'special-achievement',featured.name);return publishLiveEvent(featured.icon,`${after.name} 학생이 특별 업적 “${featured.name}”을 달성했습니다!`,'special-achievement')}
const getSetting=k=>db.prepare('SELECT value FROM settings WHERE key=?').get(k)?.value||null,setSetting=(k,v)=>db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(k,v);
const CHECKPOINT_MAX_AGE_MS=7*24*60*60*1000,CHECKPOINT_MAX_BYTES=16384,CHECKPOINT_MAX_PER_PLAYER=20,checkpointKey=name=>`activity-checkpoints:${encodeURIComponent(String(name||'').trim().slice(0,12))}`;
const ERROR_REVIEW_PREFIX='error-group-review:v1:',ERROR_REVIEW_MAX=500,errorGroupKey=row=>crypto.createHash('sha256').update([row.kind||'error',row.message||'',row.page||'',row.version||''].join('\n')).digest('hex');
const ERROR_RETENTION_KEY='error-retention-days:v1',ERROR_REPORT_MAX=2000,ERROR_RETENTION_ALLOWED=new Set([30,90,180,365]);
function errorRetentionDays(){const value=Number(getSetting(ERROR_RETENTION_KEY)||90);return ERROR_RETENTION_ALLOWED.has(value)?value:90}
function pruneErrorReports(days=errorRetentionDays()){const cutoff=new Date(Date.now()-days*86400000).toISOString();db.prepare('DELETE FROM error_reports WHERE created_at<?').run(cutoff);db.prepare('DELETE FROM error_reports WHERE id NOT IN (SELECT id FROM error_reports ORDER BY id DESC LIMIT ?)').run(ERROR_REPORT_MAX);return db.prepare('SELECT COUNT(*) AS count FROM error_reports').get().count}
function readErrorReview(groupKey){try{const value=JSON.parse(getSetting(`${ERROR_REVIEW_PREFIX}${groupKey}`)||'null');return value&&['open','resolved','ignored'].includes(value.status)&&typeof value.note==='string'&&value.note.length<=500&&Number.isFinite(Date.parse(value.updatedAt))?value:null}catch{return null}}
function saveErrorReview(groupKey,status,note){const value={status,note,updatedAt:new Date().toISOString()};setSetting(`${ERROR_REVIEW_PREFIX}${groupKey}`,JSON.stringify(value));const rows=db.prepare('SELECT key,value FROM settings WHERE key LIKE ?').all(`${ERROR_REVIEW_PREFIX}%`).map(row=>{try{return{key:row.key,updatedAt:JSON.parse(row.value)?.updatedAt||''}}catch{return{key:row.key,updatedAt:''}}}).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));for(const row of rows.slice(ERROR_REVIEW_MAX))db.prepare('DELETE FROM settings WHERE key=?').run(row.key);return value}
function readServerCheckpoints(name){let rows;try{rows=JSON.parse(getSetting(checkpointKey(name))||'[]')}catch{rows=[]}const now=Date.now(),valid=(Array.isArray(rows)?rows:[]).filter(row=>row&&typeof row.activityId==='string'&&/^[a-z0-9-]{1,80}$/.test(row.activityId)&&(row.deleted===true||row.progress&&typeof row.progress==='object'&&!Array.isArray(row.progress))&&Number.isFinite(Date.parse(row.updatedAt))&&now-Date.parse(row.updatedAt)>=0&&now-Date.parse(row.updatedAt)<=CHECKPOINT_MAX_AGE_MS).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,CHECKPOINT_MAX_PER_PLAYER);if(valid.length!==(Array.isArray(rows)?rows.length:0))setSetting(checkpointKey(name),JSON.stringify(valid));return valid}
function saveServerCheckpoint(name,activityId,progress){const id=String(activityId||'').trim();if(!/^[a-z0-9-]{1,80}$/.test(id)||!progress||typeof progress!=='object'||Array.isArray(progress))return{ok:false,code:'invalid-checkpoint'};const serialized=JSON.stringify(progress);if(!serialized||serialized.length>CHECKPOINT_MAX_BYTES)return{ok:false,code:'checkpoint-too-large'};const checkpoint={version:1,playerName:name,activityId:id,progress,updatedAt:new Date().toISOString()},rows=readServerCheckpoints(name).filter(row=>row.activityId!==id);rows.unshift(checkpoint);setSetting(checkpointKey(name),JSON.stringify(rows.slice(0,CHECKPOINT_MAX_PER_PLAYER)));return{ok:true,checkpoint}}
function clearServerCheckpoint(name,activityId){const id=String(activityId||'').trim();if(!/^[a-z0-9-]{1,80}$/.test(id))return false;const rows=readServerCheckpoints(name).filter(row=>row.activityId!==id);rows.unshift({version:1,playerName:name,activityId:id,deleted:true,updatedAt:new Date().toISOString()});setSetting(checkpointKey(name),JSON.stringify(rows.slice(0,CHECKPOINT_MAX_PER_PLAYER)));return true}
function ensureAdminPassword(){if(getSetting('admin_hash')&&getSetting('admin_salt'))return;const initial=process.env.STUDYVILLAGE_ADMIN_PASSWORD||'teacher1234',salt=crypto.randomBytes(16).toString('hex');setSetting('admin_salt',salt);setSetting('admin_hash',hashPassword(initial,salt));console.log('초기 관리자 비밀번호: teacher1234 (첫 로그인 후 변경 권장)')};ensureAdminPassword();
