app.post('/api/player/me/activity',requireSession,(req,res)=>{const activityId=String(req.body?.activityId||'').trim().slice(0,40),score=Math.max(0,Math.min(1000,Number(req.body?.score)||0));if(!/^[a-z0-9-]+$/.test(activityId))return res.status(400).json({ok:false,code:'invalid-activity'});const player=db.prepare('SELECT * FROM players WHERE name=?').get(req.session.name);if(!player)return res.status(404).json({ok:false});const now=new Date().toISOString(),existing=db.prepare('SELECT * FROM activity_records WHERE player_name=? AND activity_id=?').get(req.session.name,activityId),attempts=(existing?.attempts||0)+1,best=Math.max(existing?.best_score||0,score),total=(existing?.total_score||0)+score,gained=20+Math.floor(score/10);db.prepare(`INSERT INTO activity_records(player_name,activity_id,attempts,best_score,last_score,total_score,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(player_name,activity_id) DO UPDATE SET attempts=excluded.attempts,best_score=excluded.best_score,last_score=excluded.last_score,total_score=excluded.total_score,updated_at=excluded.updated_at`).run(req.session.name,activityId,attempts,best,score,total,now);db.prepare('UPDATE players SET xp=xp+?,updated_at=? WHERE name=?').run(gained,now,req.session.name);logActivity(req.session.name,`activity-${activityId}`,`${score}점 · +${gained}XP`);const updated=db.prepare('SELECT * FROM players WHERE name=?').get(req.session.name);announceLevelUp(player,updated);announceNpcUnlock(player,updated);res.json({ok:true,gainedXp:gained,record:{activityId,attempts,bestScore:best,lastScore:score,totalScore:total,updatedAt:now},player:safePlayer(updated)})});
