app.post('/api/admin/student-change-history/:id/undo',requireAdmin,(req,res)=>{const id=Number(req.params.id),reason=String(req.body?.reason||'').trim();if(!Number.isInteger(id)||id<1)return res.status(400).json({ok:false,code:'invalid-change-id'});if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});const change=db.prepare('SELECT id,player_name AS playerName,type,detail FROM activity_log WHERE id=?').get(id);if(!change||!['xp-correction','activity-record-correction'].includes(change.type))return res.status(404).json({ok:false,code:'change-not-undoable'});if(db.prepare("SELECT 1 FROM activity_log WHERE type='admin-change-undo' AND detail LIKE ? LIMIT 1").get(`교정 되돌리기 #${id} %`))return res.status(409).json({ok:false,code:'change-already-undone'});try{const result=db.transaction(()=>{if(change.type==='xp-correction'){const match=String(change.detail).match(/^교사 XP 교정 (\d+)→(\d+) · /);if(!match)throw Object.assign(new Error('invalid-change-detail'),{code:'invalid-change-detail'});const before=Number(match[1]),after=Number(match[2]),current=db.prepare('SELECT xp FROM players WHERE name=?').get(change.playerName);if(!current)throw Object.assign(new Error('student-not-found'),{code:'student-not-found'});if(current.xp!==after)throw Object.assign(new Error('student-state-changed'),{code:'student-state-changed'});db.prepare('UPDATE players SET xp=?,updated_at=? WHERE name=?').run(before,new Date().toISOString(),change.playerName);logActivity(change.playerName,'admin-change-undo',`교정 되돌리기 #${id} · XP ${after}→${before} · ${reason}`);return{kind:'xp',before:after,after:before}}const match=String(change.detail).match(/^교사 ([a-z0-9-]{1,40}) 기록 교정 · 도전 (\d+)→(\d+), 최고 (\d+)→(\d+), 최근 (\d+)→(\d+), 누적 (\d+)→(\d+) · /);if(!match)throw Object.assign(new Error('invalid-change-detail'),{code:'invalid-change-detail'});const activityId=match[1],before={attempts:Number(match[2]),bestScore:Number(match[4]),lastScore:Number(match[6]),totalScore:Number(match[8])},after={attempts:Number(match[3]),bestScore:Number(match[5]),lastScore:Number(match[7]),totalScore:Number(match[9])},current=db.prepare('SELECT attempts,best_score AS bestScore,last_score AS lastScore,total_score AS totalScore FROM activity_records WHERE player_name=? AND activity_id=?').get(change.playerName,activityId);if(!current)throw Object.assign(new Error('activity-record-not-found'),{code:'activity-record-not-found'});if(Object.keys(after).some(key=>current[key]!==after[key]))throw Object.assign(new Error('student-state-changed'),{code:'student-state-changed'});const now=new Date().toISOString();db.prepare('UPDATE activity_records SET attempts=?,best_score=?,last_score=?,total_score=?,updated_at=? WHERE player_name=? AND activity_id=?').run(before.attempts,before.bestScore,before.lastScore,before.totalScore,now,change.playerName,activityId);if(activityId==='riddle'){const aggregate=db.prepare('SELECT attempts,best_score AS bestScore,last_score AS lastScore,total_score AS totalScore FROM players WHERE name=?').get(change.playerName);if(!aggregate||Object.keys(after).some(key=>aggregate[key]!==after[key]))throw Object.assign(new Error('student-state-changed'),{code:'student-state-changed'});db.prepare('UPDATE players SET attempts=?,best_score=?,last_score=?,total_score=?,updated_at=? WHERE name=?').run(before.attempts,before.bestScore,before.lastScore,before.totalScore,now,change.playerName)}logActivity(change.playerName,'admin-change-undo',`교정 되돌리기 #${id} · ${activityId} 기록 복원 · ${reason}`);return{kind:'activity',activityId,before:after,after:before}})();res.json({ok:true,result})}catch(error){const code=String(error?.code||'change-undo-failed').slice(0,80);res.status(code==='student-state-changed'?409:400).json({ok:false,code})}});
