app.post('/api/admin/player/:name/reset-password',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim(),password=String(req.body?.password||'');if(password.length<4||password.length>72)return res.status(400).json({ok:false,code:'invalid-password'});if(!db.prepare('SELECT id FROM players WHERE name=?').get(name))return res.status(404).json({ok:false,code:'student-not-found'});const salt=crypto.randomBytes(16).toString('hex'),now=new Date().toISOString();db.prepare('UPDATE players SET password_hash=?,password_salt=?,updated_at=? WHERE name=?').run(hashPassword(password,salt),salt,now,name);clearStudentSessions(name);logActivity(name,'password-reset','교사가 학생 비밀번호 변경');res.json({ok:true})});
app.post('/api/admin/player/:name/xp',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim(),xp=Number(req.body?.xp),reason=String(req.body?.reason||'').trim();if(!Number.isInteger(xp)||xp<0||xp>1000000)return res.status(400).json({ok:false,code:'invalid-xp'});if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});const before=db.prepare('SELECT xp FROM players WHERE name=?').get(name);if(!before)return res.status(404).json({ok:false,code:'student-not-found'});if(before.xp===xp)return res.json({ok:true,unchanged:true,player:safePlayer(db.prepare('SELECT * FROM players WHERE name=?').get(name))});const result=db.transaction(()=>{const now=new Date().toISOString();db.prepare('UPDATE players SET xp=?,updated_at=? WHERE name=?').run(xp,now,name);logActivity(name,'xp-correction',`교사 XP 교정 ${before.xp}→${xp} · ${reason}`);return safePlayer(db.prepare('SELECT * FROM players WHERE name=?').get(name))})();res.json({ok:true,beforeXp:before.xp,afterXp:xp,player:result})});
app.post('/api/admin/player/:name/custom-title',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim(),title=normalizeCustomTitle(req.body?.title),reason=String(req.body?.reason||'').trim(),player=db.prepare('SELECT * FROM players WHERE name=?').get(name);if(!player)return res.status(404).json({ok:false,code:'student-not-found'});if(!title)return res.status(400).json({ok:false,code:'invalid-custom-title'});if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});const before=readCustomTitle(getSetting,name),level=levelFromXp(player.xp);writeCustomTitle(setSetting,name,title,before.lastStudentChangeLevel,'teacher');logActivity(name,'teacher-title-correction',`교사 칭호 수정 · ${before.title||'(없음)'}→${title} · ${reason}`);res.json({ok:true,studentChangeRightPreserved:true,player:safePlayer(player),visible:level>=60})});
app.get('/api/admin/player/:name/activity-records',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim();if(!db.prepare('SELECT id FROM players WHERE name=?').get(name))return res.status(404).json({ok:false,code:'student-not-found'});res.json({ok:true,records:activityRecordsFor(name)})});
app.post('/api/admin/player/:name/activity-records/:activityId',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim(),activityId=String(req.params.activityId||'').trim(),attempts=Number(req.body?.attempts),bestScore=Number(req.body?.bestScore),lastScore=Number(req.body?.lastScore),totalScore=Number(req.body?.totalScore),reason=String(req.body?.reason||'').trim();if(!/^[a-z0-9-]{1,40}$/.test(activityId))return res.status(400).json({ok:false,code:'invalid-activity'});if(![attempts,bestScore,lastScore,totalScore].every(Number.isInteger)||attempts<0||attempts>1000000||bestScore<0||bestScore>1000||lastScore<0||lastScore>1000||totalScore<0||totalScore>1000000000||attempts===0&&(bestScore||lastScore||totalScore)||attempts>0&&(bestScore<lastScore||totalScore<bestScore||totalScore>attempts*1000))return res.status(400).json({ok:false,code:'inconsistent-activity-record'});if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});const current=db.prepare('SELECT * FROM activity_records WHERE player_name=? AND activity_id=?').get(name,activityId);if(!current)return res.status(404).json({ok:false,code:'activity-record-not-found'});const result=db.transaction(()=>{const now=new Date().toISOString();db.prepare('UPDATE activity_records SET attempts=?,best_score=?,last_score=?,total_score=?,updated_at=? WHERE player_name=? AND activity_id=?').run(attempts,bestScore,lastScore,totalScore,now,name,activityId);if(activityId==='riddle')db.prepare('UPDATE players SET attempts=?,best_score=?,last_score=?,total_score=?,updated_at=? WHERE name=?').run(attempts,bestScore,lastScore,totalScore,now,name);logActivity(name,'activity-record-correction',`교사 ${activityId} 기록 교정 · 도전 ${current.attempts}→${attempts}, 최고 ${current.best_score}→${bestScore}, 최근 ${current.last_score}→${lastScore}, 누적 ${current.total_score}→${totalScore} · ${reason}`);return db.prepare('SELECT activity_id AS activityId,attempts,best_score AS bestScore,last_score AS lastScore,total_score AS totalScore,updated_at AS updatedAt FROM activity_records WHERE player_name=? AND activity_id=?').get(name,activityId)})();res.json({ok:true,record:result,xpUnchanged:true})});
app.post('/api/admin/player/:name/reset-equipment',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim(),reason=String(req.body?.reason||'').trim();if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});const player=db.prepare('SELECT * FROM players WHERE name=?').get(name);if(!player)return res.status(404).json({ok:false,code:'student-not-found'});const result=db.transaction(()=>{const now=new Date().toISOString();db.prepare("UPDATE players SET base_character='student-default',equipment_json='{}',updated_at=? WHERE name=?").run(now,name);logActivity(name,'equipment-repair',`교사가 꾸미기 장착 초기화 · ${reason}`);return safePlayer(db.prepare('SELECT * FROM players WHERE name=?').get(name))})();res.json({ok:true,player:result,ownedItemsPreserved:true,starsPreserved:true,xpPreserved:true})});
app.post('/api/admin/player/:name/rename',requireAdmin,(req,res)=>{const oldName=String(req.params.name||'').trim(),newName=String(req.body?.newName||'').trim().replace(/\s+/g,' '),reason=String(req.body?.reason||'').trim();if(!oldName||oldName.length>12||!newName||newName.length>12)return res.status(400).json({ok:false,code:'invalid-student-name'});if(oldName===newName)return res.status(400).json({ok:false,code:'same-student-name'});if(reason.length<3||reason.length>200)return res.status(400).json({ok:false,code:'invalid-reason'});if(!db.prepare('SELECT id FROM players WHERE name=?').get(oldName))return res.status(404).json({ok:false,code:'student-not-found'});if(db.prepare('SELECT id FROM players WHERE name=?').get(newName))return res.status(409).json({ok:false,code:'student-name-exists'});try{const result=db.transaction(()=>{const oldEncoded=encodeURIComponent(oldName),newEncoded=encodeURIComponent(newName),moves=[['compat:stars:','exact'],['compat:base-character:','exact'],['compat:owned-items:','exact'],['exploration-collection:','exact'],['custom-title:v1:','exact'],['activity-checkpoints:','checkpoint']].map(([prefix,type])=>({oldKey:`${prefix}${oldEncoded}`,newKey:`${prefix}${newEncoded}`,type}));const extraPrefix=`activity-attempt-extra:v1:${oldEncoded}:`;for(const row of db.prepare('SELECT key FROM settings WHERE key LIKE ?').all(`${extraPrefix}%`))moves.push({oldKey:row.key,newKey:`activity-attempt-extra:v1:${newEncoded}:${row.key.slice(extraPrefix.length)}`,type:'exact'});for(const move of moves){const source=db.prepare('SELECT value FROM settings WHERE key=?').get(move.oldKey);if(!source)continue;if(db.prepare('SELECT 1 FROM settings WHERE key=?').get(move.newKey))throw Object.assign(new Error('rename-settings-conflict'),{code:'rename-settings-conflict'});let value=source.value;if(move.type==='checkpoint'){let parsed;try{parsed=JSON.parse(value)}catch{throw Object.assign(new Error('invalid-checkpoint-store'),{code:'invalid-checkpoint-store'})}if(!Array.isArray(parsed))throw Object.assign(new Error('invalid-checkpoint-store'),{code:'invalid-checkpoint-store'});value=JSON.stringify(parsed.map(row=>row&&typeof row==='object'?{...row,playerName:newName}:row))}db.prepare('INSERT INTO settings(key,value) VALUES(?,?)').run(move.newKey,value);db.prepare('DELETE FROM settings WHERE key=?').run(move.oldKey)}const historyKey='activity-attempt-extra-history:v1',history=db.prepare('SELECT value FROM settings WHERE key=?').get(historyKey);if(history){let rows;try{rows=JSON.parse(history.value)}catch{throw Object.assign(new Error('invalid-extra-attempt-history'),{code:'invalid-extra-attempt-history'})}if(!Array.isArray(rows))throw Object.assign(new Error('invalid-extra-attempt-history'),{code:'invalid-extra-attempt-history'});db.prepare('UPDATE settings SET value=? WHERE key=?').run(JSON.stringify(rows.map(row=>row?.name===oldName?{...row,name:newName}:row)),historyKey)}db.prepare('UPDATE players SET name=?,updated_at=? WHERE name=?').run(newName,new Date().toISOString(),oldName);for(const table of ['activity_records','activity_log','error_reports','score_ledger','score_corrections','star_ledger'])if(db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table))db.prepare(`UPDATE ${table} SET player_name=? WHERE player_name=?`).run(newName,oldName);logActivity(newName,'account-renamed',`교사가 이름 변경 ${oldName}→${newName} · ${reason}`);return safePlayer(db.prepare('SELECT * FROM players WHERE name=?').get(newName))})();clearStudentSessions(oldName);clearStudentSessions(newName);presence.delete(oldName);res.json({ok:true,oldName,newName,player:result,sessionsRevoked:true})}catch(error){res.status(error?.code==='rename-settings-conflict'?409:400).json({ok:false,code:String(error?.code||'student-rename-failed').slice(0,80)})}});
const resetStudentRecord=db.transaction(n=>{const now=new Date().toISOString(),changed=db.prepare(`UPDATE players SET total_score=0,attempts=0,best_score=0,last_score=0,xp=0,base_character='student-default',equipment_json='{}',updated_at=? WHERE name=?`).run(now,n);if(!changed.changes)return false;db.prepare('DELETE FROM activity_records WHERE player_name=?').run(n);logActivity(n,'record-reset','교사가 학습 기록/XP/꾸미기 초기화');return true});
app.post('/api/admin/player/:name/reset-record',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim();if(!resetStudentRecord(name))return res.status(404).json({ok:false});res.json({ok:true})});
app.post('/api/admin/players/:name/reset',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim();if(!resetStudentRecord(name))return res.status(404).json({ok:false});res.json({ok:true})});
const deleteStudentData=db.transaction(name=>{if(!db.prepare('SELECT id FROM players WHERE name=?').get(name))return false;const cleanup=removeExtraAttemptStudentData({getSetting,setSetting,deleteSetting:key=>db.prepare('DELETE FROM settings WHERE key=?').run(key),listSettingKeys:prefix=>db.prepare('SELECT key FROM settings WHERE key LIKE ?').all(`${prefix}%`).map(row=>row.key)},name);if(!cleanup.ok)throw Object.assign(new Error(cleanup.code),{cleanupCode:cleanup.code});try{db.prepare('DELETE FROM score_alert_reviews WHERE ledger_id IN (SELECT id FROM score_ledger WHERE player_name=?)').run(name)}catch{}try{db.prepare('DELETE FROM score_corrections WHERE player_name=?').run(name)}catch{}try{db.prepare('DELETE FROM score_ledger WHERE player_name=?').run(name)}catch{}try{db.prepare('DELETE FROM star_ledger WHERE player_name=?').run(name)}catch{}db.prepare('DELETE FROM activity_records WHERE player_name=?').run(name);db.prepare('DELETE FROM activity_log WHERE player_name=?').run(name);db.prepare('DELETE FROM error_reports WHERE player_name=?').run(name);db.prepare('DELETE FROM settings WHERE key=?').run(`compat:stars:${encodeURIComponent(name)}`);db.prepare('DELETE FROM settings WHERE key=?').run(`exploration-collection:${encodeURIComponent(name)}`);db.prepare('DELETE FROM settings WHERE key=?').run(checkpointKey(name));db.prepare('DELETE FROM settings WHERE key=?').run(customTitleKey(name));db.prepare('DELETE FROM players WHERE name=?').run(name);return true});
app.delete('/api/admin/player/:name',requireAdmin,(req,res)=>{const name=String(req.params.name||'').trim();if(!name||name.length>12)return res.status(400).json({ok:false,code:'invalid-student'});try{if(!deleteStudentData(name))return res.status(404).json({ok:false,code:'student-not-found'})}catch(err){const reason=String(err?.cleanupCode||'').slice(0,80);if(reason)return res.status(409).json({ok:false,code:'extra-attempt-cleanup-failed',reason});return res.status(500).json({ok:false,code:'student-delete-failed'})}clearStudentSessions(name);res.json({ok:true,name})});
app.get('/api/admin/classroom-info',requireAdmin,async(_req,res)=>{const urls=classroomUrls(),preferred=urls[0]?.url||`http://${'localhost'}:${PORT}`,qrDataUrl=await QRCode.toDataURL(preferred,{width:300,margin:1});res.json({ok:true,port:PORT,urls,preferred,qrDataUrl})});
app.get('/api/admin/backup',requireAdmin,(_req,res)=>{const all=t=>{try{return db.prepare(`SELECT * FROM ${t} ORDER BY id`).all()}catch{return[]}},payload={format:'studyvillage-backup',version:CURRENT_BACKUP_VERSION,exportedAt:new Date().toISOString(),players:all('players'),settings:db.prepare('SELECT * FROM settings ORDER BY key').all(),activities:all('activity_log'),activityRecords:all('activity_records'),errorReports:all('error_reports'),scoreLedger:all('score_ledger'),scoreAlertReviews:db.prepare('SELECT * FROM score_alert_reviews ORDER BY ledger_id').all(),scoreCorrections:all('score_corrections')};res.setHeader('Content-Type','application/json; charset=utf-8');res.send(JSON.stringify(payload,null,2))});
app.post('/api/admin/restore',requireAdmin,(req,res)=>{const b=req.body;if(b?.format!=='studyvillage-backup')return res.status(400).json({ok:false});const restore=db.transaction(()=>{for(const t of ['score_corrections','score_alert_reviews','score_ledger','star_ledger','activity_records','activity_log','error_reports','players','settings']){try{db.prepare(`DELETE FROM ${t}`).run()}catch{}};const insert=(sql,rows)=>{const s=db.prepare(sql);for(const r of rows||[])s.run(r)};insert('INSERT INTO players(id,name,password_hash,password_salt,total_score,attempts,best_score,last_score,login_count,last_login_at,xp,base_character,equipment_json,owned_items_json,created_at,updated_at) VALUES(@id,@name,@password_hash,@password_salt,@total_score,@attempts,@best_score,@last_score,@login_count,@last_login_at,@xp,@base_character,@equipment_json,@owned_items_json,@created_at,@updated_at)',b.players);insert('INSERT INTO settings(key,value) VALUES(@key,@value)',b.settings);insert('INSERT INTO activity_log(id,player_name,type,detail,created_at) VALUES(@id,@player_name,@type,@detail,@created_at)',b.activities);insert('INSERT INTO activity_records(id,player_name,activity_id,attempts,best_score,last_score,total_score,updated_at) VALUES(@id,@player_name,@activity_id,@attempts,@best_score,@last_score,@total_score,@updated_at)',b.activityRecords);insert('INSERT INTO error_reports(id,player_name,report_id,kind,message,stack,page,version,user_agent,online,mode,extra_json,recent_events_json,created_at) VALUES(@id,@player_name,@report_id,@kind,@message,@stack,@page,@version,@user_agent,@online,@mode,@extra_json,@recent_events_json,@created_at)',b.errorReports);insert('INSERT INTO score_ledger(id,player_name,scope,activity_id,field,before_value,after_value,delta,source,created_at) VALUES(@id,@player_name,@scope,@activity_id,@field,@before_value,@after_value,@delta,@source,@created_at)',b.scoreLedger);insert('INSERT INTO score_alert_reviews(ledger_id,status,note,reviewed_at) VALUES(@ledger_id,@status,@note,@reviewed_at)',b.scoreAlertReviews);insert('INSERT INTO score_corrections(id,ledger_id,correction_ledger_id,player_name,scope,activity_id,field,before_value,after_value,reason,corrected_at,undone_at,undo_ledger_id) VALUES(@id,@ledger_id,@correction_ledger_id,@player_name,@scope,@activity_id,@field,@before_value,@after_value,@reason,@corrected_at,@undone_at,@undo_ledger_id)',b.scoreCorrections)});restore();ensureAdminPassword();adminSessions.clear();sessions.clear();presence.clear();liveEvents.length=0;liveEventSeq=0;res.json({ok:true,players:b.players?.length||0,auditEntries:b.scoreLedger?.length||0})});
